INSERT INTO changelog (title, body, created_at) VALUES ('Світла тема: білий + асфальт', 'Система тепер світла: білий фон і картки, текст і кнопки — темний графіт («асфальт»), бокове меню і панелі на телефоні — темний асфальт зі світлим текстом. Без синього світіння. Зелений/червоний/жовтий лишились для статусів (гроші, загроза, прострочене). Сторінка входу лишилась «космічною».', datetime('now'));
